"use client";

import { useState, useEffect } from "react";
import {
  Search,
  ChevronUp,
  ChevronDown,
  Edit,
  Trash2,
  AlertCircle,
  Loader2,
  UserCircle,
  Flag,
  Briefcase,
  Home,
  RefreshCw,
  Plus,
  Download,
  Filter,
  X,
} from "lucide-react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import * as XLSX from "xlsx";
import Layout from "./Layout";

export default function Candidates() {
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState("");
  const [candidates, setCandidates] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [sortField, setSortField] = useState("First_Name");
  const [sortDirection, setSortDirection] = useState("asc");
  const [selectedCandidates, setSelectedCandidates] = useState([]);
  const [selectCount, setSelectCount] = useState("");
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
  const [selectedCandidate, setSelectedCandidate] = useState(null);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [filterSector, setFilterSector] = useState("");
  const [filterYear, setFilterYear] = useState("");

  useEffect(() => {
    fetchCandidates();
  }, []);

  const fetchCandidates = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");

    if (!token) {
      setError("Authentification requise. Veuillez vous connecter.");
      setIsLoading(false);
      return;
    }

    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/candidates`, {
        headers: {
          Authorization: `Bearer ${token}`,
          Role: "Deputydirector",
        },
      });
      if (response.data.success) {
        setCandidates(
          response.data.data.filter(
            (candidate) => candidate.status === "candidate"
          )
        );
      } else {
        setError(
          "Échec de la récupération des candidats : " + response.data.message
        );
      }
    } catch (err) {
      setError(
        `Erreur lors de la récupération des candidats : ${
          err.response?.data?.message || err.message
        }`
      );
      console.error("Erreur de récupération des candidats :", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSort = (field) => {
    if (sortField === field) {
      setSortDirection(sortDirection === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortDirection("asc");
    }
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedCandidates(
        filteredAndSortedCandidates.map((candidate) => candidate._id)
      );
    } else {
      setSelectedCandidates([]);
    }
  };

  const handleSelectCandidate = (id) => {
    setSelectedCandidates((prev) =>
      prev.includes(id)
        ? prev.filter((candidateId) => candidateId !== id)
        : [...prev, id]
    );
  };

  const handleSelectFirstNCandidates = () => {
    const count = Number.parseInt(selectCount, 10);
    if (isNaN(count) || count <= 0) {
      setError("Veuillez entrer un nombre valide de candidats à sélectionner.");
      return;
    }
    const candidatesToSelect = filteredAndSortedCandidates
      .slice(0, count)
      .map((c) => c._id);
    setSelectedCandidates(candidatesToSelect);
  };

  const handleMarkSelected = async () => {
    if (selectedCandidates.length === 0) {
      setError("Aucun candidat sélectionné.");
      return;
    }

    const token = localStorage.getItem("token");
    if (!token) {
      setError("Jeton d'authentification manquant. Veuillez vous reconnecter.");
      return;
    }

    try {
      const updatePromises = selectedCandidates.map((id) =>
        axios.patch(
          `${process.env.REACT_APP_API_URL}/api/candidates/${id}/status`,
          { status: "selected" },
          {
            headers: {
              Authorization: `Bearer ${token}`,
              Role: "Deputydirector",
            },
          }
        )
      );

      await Promise.all(updatePromises);
      fetchCandidates();
      setSelectedCandidates([]);
      setError("");
    } catch (err) {
      setError(
        `Échec de la sélection des candidats : ${
          err.response?.data?.message || err.message
        }`
      );
      console.error("Erreur de sélection des candidats :", err);
    }
  };

  const handleCreateCandidate = () => {
    navigate("/CreateCandidate");
  };

  const handleEditCandidate = (id) => {
    navigate(`/EditCandidate/${id}`);
  };

  const handleDeleteCandidate = async (id) => {
    if (window.confirm("Êtes-vous sûr de vouloir supprimer ce candidat ?")) {
      try {
        const token = localStorage.getItem("token");
        await axios.delete(`${process.env.REACT_APP_API_URL}/api/candidates/${id}`, {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "Deputydirector",
          },
        });
        setCandidates(candidates.filter((c) => c._id !== id));
        setSelectedCandidates(
          selectedCandidates.filter((candidateId) => candidateId !== id)
        );
      } catch (err) {
        setError(
          "Échec de la suppression du candidat : " +
            (err.response?.data?.message || err.message)
        );
      }
    }
  };

  const openDetailsModal = (candidate) => {
    setSelectedCandidate(candidate);
    setIsDetailsModalOpen(true);
  };

  const closeDetailsModal = () => {
    setIsDetailsModalOpen(false);
    setSelectedCandidate(null);
  };

  const filteredAndSortedCandidates = candidates
    .filter((candidate) => {
      const firstName = (candidate.First_Name || "").toLowerCase();
      const lastName = (candidate.Last_Name || "").toLowerCase();
      const cff = (candidate.CFF || "").toLowerCase();
      const hometown = (candidate.hometown || "").toLowerCase();
      const sector = (candidate.Sector || "").toLowerCase();
      const createdYear = candidate.createdAt
        ? new Date(candidate.createdAt).getFullYear().toString()
        : "";

      const matchesSearch =
        `${firstName} ${lastName}`.includes(searchQuery.toLowerCase()) ||
        cff.includes(searchQuery.toLowerCase()) ||
        hometown.includes(searchQuery.toLowerCase());
      const matchesSector =
        !filterSector || sector === filterSector.toLowerCase();
      const matchesYear = !filterYear || createdYear === filterYear;

      return matchesSearch && matchesSector && matchesYear;
    })
    .sort((a, b) => {
      if (sortField === "Name") {
        const nameA = `${a.First_Name || ""} ${
          a.Last_Name || ""
        }`.toLowerCase();
        const nameB = `${b.First_Name || ""} ${
          b.Last_Name || ""
        }`.toLowerCase();
        return sortDirection === "asc"
          ? nameA.localeCompare(nameB)
          : nameB.localeCompare(nameA);
      }
      const valueA = (a[sortField] || "").toString().toLowerCase();
      const valueB = (b[sortField] || "").toString().toLowerCase();
      return sortDirection === "asc"
        ? valueA.localeCompare(valueB)
        : valueB.localeCompare(valueA);
    });

  const handleExportToExcel = () => {
  const exportData = filteredAndSortedCandidates.map((candidate) => {
    const criteriaData = candidate.criteria.reduce((acc, crit) => {
      const criterionName = crit.criterionId?.name || "Critère inconnu";
      acc[criterionName] = `${crit.description} (${crit.points} points)`;
      return acc;
    }, {});
    return {
      CFF: candidate.CFF || "",
      Prénom: candidate.First_Name || "",
      Nom: candidate.Last_Name || "",
      Genre: candidate.Gender || "",
      Nationalité: candidate.Nationality || "",
      Secteur: candidate.Sector || "",
      "Ville d'origine": candidate.hometown || "",
      Note: candidate.Note || "",
      Observation: candidate.Observation || "",
      "Critères géographiques": candidate.geographic_criteria || "",
      Statut: candidate.status || "",
      "Créé le": candidate.createdAt
        ? new Date(candidate.createdAt).toLocaleString("fr-FR")
        : "",
      "Mis à jour le": candidate.updatedAt
        ? new Date(candidate.updatedAt).toLocaleString("fr-FR")
        : "",
      ...criteriaData,
    };
  });

  const ws = XLSX.utils.json_to_sheet(exportData);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Candidats");
  XLSX.writeFile(wb, "Exportation_Candidats.xlsx");
  setIsDropdownOpen(false);
};

  const getSortIcon = (field) => {
    if (sortField !== field) return null;
    return sortDirection === "asc" ? (
      <ChevronUp className="h-4 w-4" />
    ) : (
      <ChevronDown className="h-4 w-4" />
    );
  };

  const uniqueSectors = [
    ...new Set(candidates.map((candidate) => candidate.Sector)),
  ].filter(Boolean);
  const uniqueYears = [
    ...new Set(
      candidates.map((candidate) =>
        candidate.createdAt
          ? new Date(candidate.createdAt).getFullYear().toString()
          : ""
      )
    ),
  ]
    .filter(Boolean)
    .sort((a, b) => b - a);

  return (
    <Layout>
      <div className="container mx-auto px-4 py-6">
        <div className="border-none shadow-lg bg-white rounded-xl">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white rounded-t-xl p-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
              <div>
                <h2 className="text-2xl font-bold tracking-tight">
                  Gestion des Candidats
                </h2>
                <p className="text-white mt-1">
                  Afficher et gérer les candidats
                </p>
              </div>
              <button
                onClick={handleCreateCandidate}
                className="px-4 py-2 bg-white text-[#00717F] rounded-md shadow-sm hover:bg-[#C8A45D/20] flex items-center gap-2 text-sm font-medium transition-colors"
              >
                <Plus className="h-4 w-4" />
                Ajouter un candidat
              </button>
            </div>
          </div>
          <div className="p-0">
            <div className="p-4 border-b border-gray-200">
              <div className="flex flex-col md:flex-row gap-4">
                <div className="relative flex-1">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Search className="h-4 w-4 text-gray-400" />
                  </div>
                  <input
                    className="pl-9 w-full border border-gray-300 rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500 placeholder-gray-400"
                    placeholder="Rechercher par nom, CFF ou ville..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                  />
                </div>
                <div className="flex items-center gap-2">
                  <div className="group relative">
                    <button
                      onClick={fetchCandidates}
                      className="h-10 w-10 border border-gray-300 rounded-md flex items-center justify-center hover:bg-gray-100 transition-colors"
                    >
                      <RefreshCw className="h-4 w-4 text-#333333" />
                    </button>
                    <span className="absolute hidden group-hover:block bg-gray-800 text-white text-xs rounded-md px-2 py-1 -top-8 left-1/2 transform -translate-x-1/2">
                      Actualiser
                    </span>
                  </div>
                  <div className="relative">
                    <button
                      onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                      className="h-10 w-10 border border-gray-300 rounded-md flex items-center justify-center hover:bg-gray-100 transition-colors"
                    >
                      <Filter className="h-4 w-4 text-#333333" />
                    </button>
                    {isDropdownOpen && (
                      <div className="absolute right-0 mt-2 w-48 bg-white border border-gray-200 rounded-md shadow-lg z-10">
                        <button
                          onClick={handleExportToExcel}
                          className="w-full flex items-center gap-2 px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 transition-colors"
                        >
                          <Download className="h-4 w-4" />
                          Exporter vers Excel
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </div>
              <div className="mt-4 flex flex-col md:flex-row gap-4">
                <div className="relative flex-1">
                  <select
                    className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
                    value={filterSector}
                    onChange={(e) => setFilterSector(e.target.value)}
                  >
                    <option value="">Tous les secteurs</option>
                    {uniqueSectors.map((sector) => (
                      <option key={sector} value={sector}>
                        {sector}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="relative flex-1">
                  <select
                    className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
                    value={filterYear}
                    onChange={(e) => setFilterYear(e.target.value)}
                  >
                    <option value="">Toutes les années</option>
                    {uniqueYears.map((year) => (
                      <option key={year} value={year}>
                        {year}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
              <div className="mt-4 flex items-center gap-2">
                <input
                  type="number"
                  value={selectCount}
                  onChange={(e) => setSelectCount(e.target.value)}
                  placeholder="Nombre de candidats"
                  min="1"
                  className="w-32 rounded-md border border-gray-300 py-2 px-3 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
                />
                <button
                  onClick={handleSelectFirstNCandidates}
                  className="px-3 py-2 bg-[#00717F] text-white rounded-md hover:bg-[#00717F]/90 text-sm font-medium transition-colors"
                >
                  Sélectionner les premiers
                </button>
                <button
                  onClick={handleMarkSelected}
                  className="px-3 py-2 bg-emerald-600 text-white rounded-md hover:bg-emerald-700 text-sm font-medium transition-colors disabled:bg-gray-400"
                  disabled={selectedCandidates.length === 0}
                >
                  Marquer comme sélectionné
                </button>
                {selectedCandidates.length > 0 && (
                  <span className="text-sm text-#333333">
                    {selectedCandidates.length} candidat(s) sélectionné(s)
                  </span>
                )}
              </div>
            </div>

            {error && (
              <div className="m-4 p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3 rounded-md">
                <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
                <p className="text-red-700">{error}</p>
              </div>
            )}

            {isLoading ? (
              <div className="flex justify-center items-center h-64">
                <div className="flex flex-col items-center gap-2">
                  <Loader2 className="h-8 w-8 text-amber-700 animate-spin" />
                  <p className="text-gray-500">Chargement des candidats...</p>
                </div>
              </div>
            ) : filteredAndSortedCandidates.length === 0 ? (
              <div className="flex flex-col justify-center items-center h-64 text-gray-500">
                <UserCircle className="h-16 w-16 text-gray-300 mb-2" />
                <p className="mb-2">Aucun candidat trouvé</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="bg-gray-100 border-b">
                      <th className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        <input
                          type="checkbox"
                          checked={
                            selectedCandidates.length ===
                            filteredAndSortedCandidates.length
                          }
                          onChange={handleSelectAll}
                          className="rounded border-gray-300 text-amber-700 focus:ring-amber-500"
                        />
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("CFF")}
                      >
                        <div className="flex items-center gap-1">
                          CFF {getSortIcon("CFF")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("Name")}
                      >
                        <div className="flex items-center gap-1">
                          Nom {getSortIcon("Name")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("Gender")}
                      >
                        <div className="flex items-center gap-1">
                          Genre {getSortIcon("Gender")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("Nationality")}
                      >
                        <div className="flex items-center gap-1">
                          Nationalité {getSortIcon("Nationality")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("Sector")}
                      >
                        <div className="flex items-center gap-1">
                          Secteur {getSortIcon("Sector")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("hometown")}
                      >
                        <div className="flex items-center gap-1">
                          Ville {getSortIcon("hometown")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("Note")}
                      >
                        <div className="flex items-center gap-1">
                          Note {getSortIcon("Note")}
                        </div>
                      </th>
                      <th className="py-3 px-4 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y">
                    {filteredAndSortedCandidates.map((candidate) => (
                      <tr
                        key={candidate._id}
                        className="group hover:bg-gray-50 transition-colors cursor-pointer border-l-4 border-l-blue-400"
                        onClick={() => openDetailsModal(candidate)}
                      >
                        <td
                          className="py-4 px-4"
                          onClick={(e) => e.stopPropagation()}
                        >
                          <input
                            type="checkbox"
                            checked={selectedCandidates.includes(candidate._id)}
                            onChange={() => handleSelectCandidate(candidate._id)}
                            className="rounded border-gray-300 text-amber-700 focus:ring-amber-500"
                          />
                        </td>
                        <td className="py-4 px-4 text-sm font-medium">
                          {candidate.CFF || ""}
                        </td>
                        <td className="py-4 px-4">
                          <div className="flex items-center">
                            <div className="text-sm font-medium">
                              {candidate.First_Name || ""}{" "}
                              {candidate.Last_Name || ""}
                            </div>
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-#333333">
                          {candidate.Gender || ""}
                        </td>
                        <td className="py-4 px-4 text-sm text-#333333">
                          <div className="flex items-center gap-2">
                            <Flag className="h-4 w-4 text-amber-700/60" />
                            {candidate.Nationality || ""}
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-#333333">
                          <div className="flex items-center gap-2">
                            <Briefcase className="h-4 w-4 text-amber-700/60" />
                            {candidate.Sector || ""}
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-#333333">
                          <div className="flex items-center gap-2">
                            <Home className="h-4 w-4 text-amber-700/60" />
                            {candidate.hometown || ""}
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-#333333 max-w-[200px]">
                          <div className="flex items-center gap-2">
                            <span
                              className="truncate"
                              title={candidate.Note || "Aucune note disponible"}
                            >
                              {candidate.Note || "Aucune note disponible"}
                            </span>
                          </div>
                        </td>
                        <td
                          className="py-4 px-4 text-sm text-#333333"
                          onClick={(e) => e.stopPropagation()}
                        >
                          <div className="flex items-center gap-2 justify-end">
                            <div className="group relative">
                              <button
                                onClick={() => handleEditCandidate(candidate._id)}
                                className="h-8 w-8 text-blue-600 hover:bg-blue-50 rounded-full flex items-center justify-center transition-colors"
                              >
                                <Edit className="h-4 w-4" />
                              </button>
                              <span className="absolute hidden group-hover:block bg-gray-800 text-white text-xs rounded-md px-2 py-1 -top-8 left-1/2 transform -translate-x-1/2">
                                Modifier
                              </span>
                            </div>
                            <div className="group relative">
                              <button
                                onClick={() =>
                                  handleDeleteCandidate(candidate._id)
                                }
                                className="h-8 w-8 text-red-600 hover:bg-red-50 rounded-full flex items-center justify-center transition-colors"
                              >
                                <Trash2 className="h-4 w-4" />
                              </button>
                              <span className="absolute hidden group-hover:block bg-gray-800 text-white text-xs rounded-md px-2 py-1 -top-8 left-1/2 transform -translate-x-1/2">
                                Supprimer
                              </span>
                            </div>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>

      {isDetailsModalOpen && selectedCandidate && (
  <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
    <div className="bg-white rounded-lg p-6 w-full max-w-lg shadow-xl max-h-[80vh] overflow-y-auto">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-xl font-bold text-[#00717F]">
          Détails du Candidat
        </h2>
        <span className="px-2 py-1 bg-blue-100 text-blue-800 hover:bg-blue-200 text-xs font-medium rounded-full">
          {selectedCandidate.status || "Candidat"}
        </span>
      </div>

      <div className="bg-gray-100 p-4 rounded-lg mb-4">
        <div className="flex items-center gap-3 mb-3">
          <div className="h-12 w-12 rounded-full bg-amber-100 flex items-center justify-center text-[#00717F] shadow-sm">
            <UserCircle className="h-7 w-7" />
          </div>
          <div>
            <h3 className="text-lg font-semibold">
              {selectedCandidate.First_Name || ""}{" "}
              {selectedCandidate.Last_Name || ""}
            </h3>
            <p className="text-sm text-gray-500">
              CFF : {selectedCandidate.CFF || ""}
            </p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-#333333">
        <div className="space-y-3 md:border-r md:pr-4">
          <p>
            <strong className="text-[#00717F]">Genre :</strong>{" "}
            {selectedCandidate.Gender || ""}
          </p>
          <p>
            <strong className="text-[#00717F]">Nationalité :</strong>{" "}
            {selectedCandidate.Nationality || ""}
          </p>
          <p>
            <strong className="text-[#00717F]">Secteur :</strong>{" "}
            {selectedCandidate.Sector || ""}
          </p>
          <p>
            <strong className="text-[#00717F]">Ville d'origine :</strong>{" "}
            {selectedCandidate.hometown || ""}
          </p>
          <p>
            <strong className="text-[#00717F]">Note :</strong>{" "}
            {selectedCandidate.Note || "Aucune note disponible"}
          </p>
          <p>
            <strong className="text-[#00717F]">Observation :</strong>{" "}
            {selectedCandidate.Observation || "N/A"}
          </p>
          <p>
            <strong className="text-[#00717F]">Numéro de téléphone :</strong>{" "}<br></br>
            {selectedCandidate.phoneNumber || "N/A"}
          </p>
          <p>
            <strong className="text-[#00717F]">Numéro de téléphone des parents :</strong>{" "}<br></br>
            {selectedCandidate.parentPhoneNumber || "N/A"}
          </p>
        </div>
        <div className="space-y-3">
          {selectedCandidate.criteria && selectedCandidate.criteria.length > 0 ? (
            selectedCandidate.criteria.map((crit, index) => (
              <p key={index}>
                <strong className="text-[#00717F]">
                  {crit.criterionId?.name || "Critère inconnu"} :
                </strong>{" "}
                {crit.description} ({crit.points} points)
              </p>
            ))
          ) : (
            <p>Aucun critère défini</p>
          )}
          <p>
            <strong className="text-[#00717F]">
              Critères géographiques :
            </strong>{" "}
            {selectedCandidate.geographic_criteria || "0"} points
          </p>
          <p>
            <strong className="text-[#00717F]">Statut :</strong>{" "}
            <span className="px-2 py-0.5 bg-blue-100 text-blue-800 text-xs font-medium rounded-full">
              {selectedCandidate.status || ""}
            </span>
          </p>
        </div>
      </div>

      <div className="flex justify-between items-center gap-2 pt-4 border-t">
        <div className="text-xs text-gray-500">
          <p>
            Créé le :{" "}
            {selectedCandidate.createdAt
              ? new Date(selectedCandidate.createdAt).toLocaleString(
                  "fr-FR"
                )
              : ""}
          </p>
          <p>
            Mis à jour le :{" "}
            {selectedCandidate.updatedAt
              ? new Date(selectedCandidate.updatedAt).toLocaleString(
                  "fr-FR"
                )
              : ""}
          </p>
        </div>
        <button
          onClick={closeDetailsModal}
          className="px-4 py-2 bg-[#00717F] text-white rounded-md hover:bg-[#00717F] transition-colors"
        >
          Fermer
        </button>
      </div>
    </div>
  </div>
)}
    </Layout>
  );
}
